local function State2Num(state)
    if state == XDataCenter.TaskManager.TaskState.Achieved then
        return 1
    end
    if state == XDataCenter.TaskManager.TaskState.Finish then
        return -1
    end
    return 0
end

local function CompareState(stateA, stateB)
    if stateA == stateB then
        return 0
    end
    local a = State2Num(stateA)
    local b = State2Num(stateB)
    if a > b then return 1 end
    if a < b then return -1 end
    return 0
end

